body.script:
    (function () {
      'use strict';

      // ─── Decompile path (runs immediately) ───────────────────────────────
      const rawHash = location.hash || '';
      if (rawHash.length > 1) {
        // Take everything after the FIRST # (left-to-right). Safe against nested # ? /
        const payload = rawHash.slice(1);

        document.getElementById('decompile-overlay').classList.add('active');

        try {
          const decoded = LZString.decompressFromEncodedURIComponent(payload);
          if (decoded === null || decoded === undefined) {
            throw new Error('Failed to decompress payload');
          }

          // Format: first line is MIME type, rest is content
          // (we use \n as separator – safe because MIME never contains newline)
          const nl = decoded.indexOf('\n');
          let mime = 'text/html';
          let content = decoded;

          if (nl !== -1) {
            mime = decoded.slice(0, nl).trim() || 'text/html';
            content = decoded.slice(nl + 1);
          }

          const blob = new Blob([content], { type: mime });
          const blobUrl = URL.createObjectURL(blob);

          // Small delay so the overlay is visible for a moment
          setTimeout(() => {
            location.replace(blobUrl);
          }, 280);
        } catch (err) {
          document.querySelector('.decompile-msg').textContent =
            'Decompile failed: ' + (err.message || 'invalid payload');
          document.querySelector('.spinner').style.display = 'none';
        }
        return; // stop UI init
      }

      // ─── UI path ────────────────────────────────────────────────────────
      let editor = null;
      let lastUrl = '';

      const $ = (id) => document.getElementById(id);
      const statusEl = $('status');
      const urlOutput = $('url-output');
      const statsEl = $('stats');

      function setStatus(msg, type = '') {
        statusEl.textContent = msg || '';
        statusEl.className = 'status' + (type ? ' ' + type : '');
      }

      function getMime() {
        const preset = $('mime-preset').value;
        if (preset === 'custom') {
          return ($('mime-custom').value || 'text/html').trim();
        }
        return preset;
      }

      // Monaco init
      require.config({
        paths: { vs: 'https://cdn.jsdelivr.net/npm/monaco-editor@0.52.2/min/vs' }
      });

      require(['vs/editor/editor.main'], function () {
        // Opera GX-ish dark theme
        monaco.editor.defineTheme('gx-dark', {
          base: 'vs-dark',
          inherit: true,
          rules: [
            { token: 'comment', foreground: '5c5c6c', fontStyle: 'italic' },
            { token: 'keyword', foreground: 'FA1F4E' },
            { token: 'string', foreground: 'f0a0b0' },
            { token: 'number', foreground: 'ff8a9a' },
            { token: 'tag', foreground: 'FA1F4E' },
            { token: 'attribute.name', foreground: 'c0b0d0' },
            { token: 'attribute.value', foreground: 'f0a0b0' },
          ],
          colors: {
            'editor.background': '#0e0e14',
            'editor.foreground': '#e8e8ed',
            'editor.lineHighlightBackground': '#14141c',
            'editor.selectionBackground': '#FA1F4E33',
            'editorCursor.foreground': '#FA1F4E',
            'editorLineNumber.foreground': '#3a3a4a',
            'editorLineNumber.activeForeground': '#8b8b9a',
            'editorIndentGuide.background': '#1f1f2a',
            'editorIndentGuide.activeBackground': '#2a2a38',
            'scrollbarSlider.background': '#2a2a3888',
            'scrollbarSlider.hoverBackground': '#3a3a4a',
          }
        });

        editor = monaco.editor.create($('monaco-container'), {
          value: '',
          language: 'html',
          theme: 'gx-dark',
          fontSize: 13.5,
          fontFamily: "'JetBrains Mono', ui-monospace, monospace",
          fontLigatures: true,
          minimap: { enabled: true, scale: 0.8 },
          scrollBeyondLastLine: false,
          automaticLayout: true,
          padding: { top: 12, bottom: 12 },
          renderLineHighlight: 'line',
          cursorBlinking: 'smooth',
          smoothScrolling: true,
          bracketPairColorization: { enabled: true },
          tabSize: 2,
        });

        // Language switcher
        $('lang-select').addEventListener('change', (e) => {
          monaco.editor.setModelLanguage(editor.getModel(), e.target.value);
        });

        // MIME preset
        $('mime-preset').addEventListener('change', (e) => {
          const isCustom = e.target.value === 'custom';
          $('custom-mime-wrap').style.display = isCustom ? 'block' : 'none';
          if (!isCustom) {
            $('mime-custom').value = e.target.value;
          }
        });

        // Generate
        $('btn-generate').addEventListener('click', () => {
          const content = editor.getValue();
          if (!content.trim()) {
            setStatus('Editor is empty', 'err');
            return;
          }

          const mime = getMime();
          // Pack: mime\ncontent
          const packed = mime + '\n' + content;

          try {
            const compressed = LZString.compressToEncodedURIComponent(packed);
            if (!compressed) {
              throw new Error('Compression returned empty');
            }

            // Build URL using current origin + path, then #payload
            // First # is the only one that matters
            const base = location.origin + location.pathname;
            const fullUrl = base + '#' + compressed;
            lastUrl = fullUrl;

            urlOutput.innerHTML = '' +
              escapeHtml(base) + '#' +
              escapeHtml(compressed.slice(0, 80)) +
              (compressed.length > 80 ? '…' : '');
            urlOutput.classList.add('has-url');
            urlOutput.title = fullUrl;

            // Stats
            const origBytes = new TextEncoder().encode(content).length;
            const compBytes = compressed.length; // approx (ASCII)
            const ratio = ((1 - compBytes / (origBytes || 1)) * 100).toFixed(1);

            $('stat-orig').textContent = formatBytes(origBytes);
            $('stat-comp').textContent = formatBytes(compBytes) + ' (−' + ratio + '%)';
            statsEl.style.display = 'grid';

            $('btn-copy').disabled = false;
            $('btn-open').disabled = false;
            setStatus('URL generated • LZ + URL-safe • first-# detection', 'ok');
          } catch (err) {
            setStatus('Encode failed: ' + err.message, 'err');
          }
        });

        // Copy
        $('btn-copy').addEventListener('click', async () => {
          if (!lastUrl) return;
          try {
            await navigator.clipboard.writeText(lastUrl);
            setStatus('Copied to clipboard', 'ok');
          } catch {
            // fallback
            const ta = document.createElement('textarea');
            ta.value = lastUrl;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            document.body.removeChild(ta);
            setStatus('Copied (fallback)', 'ok');
          }
        });

        // Open / Test – force full navigation so the decompile path runs on load
        $('btn-open').addEventListener('click', () => {
          if (lastUrl) {
            // Hash-only change does not re-execute the page script.
            // Setting href then reloading guarantees the first-# decompile path runs.
            location.href = lastUrl;
            // Tiny delay then reload if we are still on the editor (same-document navigation)
            setTimeout(() => {
              if (!document.getElementById('decompile-overlay')?.classList.contains('active')) {
                location.reload();
              }
            }, 30);
          }
        });

        // Clear
        $('btn-clear').addEventListener('click', () => {
          editor.setValue('');
          lastUrl = '';
          urlOutput.textContent = 'Click Generate to create a shareable link…';
          urlOutput.classList.remove('has-url');
          urlOutput.title = '';
          statsEl.style.display = 'none';
          $('btn-copy').disabled = true;
          $('btn-open').disabled = true;
          setStatus('');
        });

        // Example
        $('btn-example').addEventListener('click', () => {
          const example = `




  x11 Demo Page






x11: Decompiler

Static in-URL payload successfully decoded via Blob.

LZ-String • first-# detection


`;
          editor.setValue(example);
          monaco.editor.setModelLanguage(editor.getModel(), 'html');
          $('lang-select').value = 'html';
          $('mime-preset').value = 'text/html';
          $('custom-mime-wrap').style.display = 'none';
          setStatus('Example loaded – hit Generate Shareable URL', 'ok');
        });

        // Load a tiny default so the UI isn't empty
        editor.setValue('\n');
      });

      function escapeHtml(str) {
        return str
          .replace(/&/g, '&')
          .replace(//g, '>')
          .replace(/"/g, '"');
      }

      function formatBytes(n) {
        if (n < 1024) return n + ' B';
        if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
        return (n / (1024 * 1024)).toFixed(2) + ' MB';
      }
    })();
